import {venueSetup} from '/venue-setup.mjs';
import {schedulePage,openScheduleEditor} from '/schedules.mjs';
import {billboardPage,mountBillboards} from '/billboards.mjs';
import {gameHostPage,mountGameHost} from '/game-host.mjs';
import {environmentPanel,openEnvironmentEditor} from '/curator-environments.mjs';
import {WORLDS,THEMES} from '/shared/domain.mjs';
const $=s=>document.querySelector(s);
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n||0)/100);
const date=n=>n?new Date(n).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const clone=o=>JSON.parse(JSON.stringify(o));
const defaultMix={mode:'single',worlds:{golf:'normal'},subcategories:{},minutes:180,seed:1};
const S={session:null,config:null,data:null,venueId:localStorage.getItem('mixx-venue')||'',page:'home',auth:'signup',draft:clone(defaultMix),theme:'modern-luxury',accent:'#c7aa77',selected:new Set(),billing:null,revenue:null,admin:null,brands:null,playerVolume:70,audioStatus:'No audio command sent.',busy:false};
const paths={home:'Home',mixx:'Choose your MIXX',tvs:'TVs & remote',schedule:'Schedule',commerce:'My Billboard',revenue:'Earnings & QR',billing:'Plan & installation',games:'Bourbon Games',admin:'MIXXTANK Admin',brands:'Brand reports'};
const venueWrites=new Set(['pair','save-mix','apply-mix','remote','world','mode','weight','subcategory','edit-tv','revoke-tv','audio-volume','audio-mute','quick-command','tv-remote']);
const icons={home:'M3 10l9-7 9 7v10a1 1 0 01-1 1h-5v-7H9v7H4a1 1 0 01-1-1z',play:'M7 4l14 8-14 8z',pause:'M8 5v14M16 5v14',next:'M5 5l11 7-11 7zM19 5v14',shuffle:'M3 7h3c5 0 7 10 12 10h3M18 14l3 3-3 3M3 17h3c5 0 7-10 12-10h3M18 4l3 3-3 3',tv:'M3 4h18v13H3zM8 21h8M12 17v4',brush:'M14 4l6 6M4 20l4-1L21 6a2 2 0 00-3-3L5 16z',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16',megaphone:'M3 10v5h5l10 5V5L8 10zM8 15l2 6M21 9v7',chart:'M4 20V4M4 20h17M9 16V9M14 16V5M19 16v-4',card:'M3 5h18v14H3zM3 10h18M7 15h3',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',check:'M5 12l4 4L20 5',close:'M6 6l12 12M18 6L6 18',arrow:'M4 12h15M13 6l6 6-6 6',plus:'M12 4v16M4 12h16',help:'M9 9a3 3 0 116 0c0 2-3 2-3 4M12 17h.01M22 12a10 10 0 11-20 0 10 10 0 0120 0',menu:'M4 6h16M4 12h16M4 18h16',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',glass:'M6 3h12l-1 12H7zM12 15v6M8 21h8M7 9h10',flag:'M6 22V3l14 4-14 5M3 22h8',compass:'M16 8l-3 5-5 3 3-5zM22 12a10 10 0 11-20 0 10 10 0 0120 0',wind:'M3 8h12c5 0 5-6 1-6M3 12h16c4 0 4 6 0 6M3 16h7c4 0 4 6 1 6',fork:'M5 2v7a3 3 0 006 0V2M8 2v20M18 2c-3 4-3 10 1 10v10M19 2v10',cocktail:'M3 4h18l-9 10zM12 14v7M7 21h10M7 8h10',music:'M9 18V5l11-2v13M9 7l11-2M9 18c0 3-6 4-6 1 0-3 6-4 6-1M20 16c0 3-6 4-6 1 0-3 6-4 6-1',mountain:'M2 20L9 5l5 10 3-5 5 10zM6 11l3 2 2-3',link:'M10 14l4-4M8 16l-1 1a4 4 0 01-6-6l5-5a4 4 0 016 0M16 8l1-1a4 4 0 016 6l-5 5a4 4 0 01-6 0',cloud:'M7 18H5a4 4 0 01-1-8 7 7 0 0113-2 5 5 0 011 10h-2M12 12v10M8 18l4 4 4-4',settings:'M12 8a4 4 0 100 8 4 4 0 000-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.play}"/></svg>`;}
function button(label,action,style='',extra=''){return `<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5500);}
async function api(path,body,method,{signal}={}){
  const options={method:method||(body?'POST':'GET'),credentials:'same-origin',signal,headers:{'X-Venue-Id':S.venueId,'X-CSRF-Token':S.session?.csrf||''}};
  if(body!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body);}
  const r=await fetch('/api'+path,options);const data=await r.json();if(!r.ok){const e=new Error(data.error||'Unable to complete the request.');e.status=r.status;throw e;}return data;
}
function mixName(m=S.draft){const worlds=Object.keys(m.worlds).map(id=>WORLDS.find(w=>w.id===id)?.name||id);return m.mode==='single'?`${worlds[0]} MIXX`:'My Mix';}
function landscape(){return `<div class="landscape"><svg viewBox="0 0 500 220" fill="none"><path d="M-50 210Q100-80 370 130T600 40M-20 245Q150-20 360 170T620 80M-40 120Q100-20 300 70T580-10" stroke-width="1"/><path d="M267 151V26l56 15-56 17M239 158q30-9 55 0" stroke-width="2"/><ellipse cx="265" cy="158" rx="40" ry="7" stroke-width="1"/></svg></div>`;}
function preview(m=S.draft,themeId=S.theme){const t=THEMES.find(t=>t.id===themeId)||THEMES[0],accent=t.id==='custom'?S.accent:t.color;return `<div class="tv-preview" style="--tv-bg:${t.bg};--tv-accent:${h(accent)}">${landscape()}<div class="top"><span>MIXXTANK</span><span>TV preview</span></div><div class="program"><div class="eyebrow" style="color:inherit">${h(mixName(m))} · ${h(t.name)}</div><h2>Your room.<br>Your kind of stories.</h2><p>${h(S.data?.venue.name||'Your venue')} · ${m.minutes} minute rotation</p></div></div>`;}
function header(title,subtitle,action=''){return `<header class="header"><div><div class="eyebrow">MIXXTANK for venues</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</header>`;}
function note(t){return `<div class="footer-note">${icon('shield')}<span>${t}</span></div>`;}
function empty(title,body,action='',i='tv'){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${body}</p>${action}</div>`;}
function stats(){const m=S.data.metrics;return `<div class="grid cols4 stats"><div class="panel metric"><span class="metric-label">TVs connected ${icon('tv')}</span><b class="metric-value">${S.data.tvs.filter(t=>t.online).length}<small> / ${S.data.tvs.length}</small></b><span class="metric-note">From current player heartbeats</span></div><div class="panel metric"><span class="metric-label">QR scans · 30 days ${icon('link')}</span><b class="metric-value">${m.scans.toLocaleString()}</b><span class="metric-note">Consented QR visits</span></div><div class="panel metric"><span class="metric-label">Attributed sales ${icon('chart')}</span><b class="metric-value">${money(m.salesCents)}</b><span class="metric-note">Net merchandise after refunds</span></div><div class="panel metric"><span class="metric-label">Your earnings · 30 days ${icon('glass')}</span><b class="metric-value">${money(m.earnedCents)}</b><span class="metric-note">Accrued share, not a paid balance</span></div></div>`;}
function worldCards(selected,limit=8){return `<div class="worlds">${WORLDS.slice(0,limit).map(w=>`<button class="world ${selected.includes(w.id)?'selected':''}" type="button" data-action="world" data-id="${w.id}" aria-pressed="${selected.includes(w.id)}" style="--world:${w.color}"><div class="world-art">${icon(w.icon)}</div><div class="world-body"><b>${h(w.name)} ${selected.includes(w.id)?icon('check'):icon('arrow')}</b><p>${h(w.description)}</p></div></button>`).join('')}</div>`;}
function home(){const d=S.data,connected=d.tvs.length>0;return header('Home.','Your venue, ready for the day.')+
 venueSetup({...d,worlds:WORLDS,origin:location.origin})+
 (connected?`<section class="panel room-control streamlined-remote"><div class="full"><div class="eyebrow">VENUE REMOTE</div><h2>Control the room</h2></div><div class="mini-world"><span class="mini-icon">${icon('flag')}</span><div><b>${h(mixName(d.venue.mix))}</b><p>Your saved venue programming</p></div></div>${button(icon('play')+' Keep playing','remote','','data-kind="play"')}${button(icon('shuffle')+' Shuffle the rotation','remote','secondary','data-kind="shuffle"')}${button('Choose a different MIXX '+icon('arrow'),'nav','ghost','data-page="mixx"')}</section><section class="section">${stats()}</section>`:'')+
 note('Your phone or computer is the remote. Keep the paired TV player open on the TV device.');}
function mixx(){const selected=Object.keys(S.draft.worlds);return header('Find your MIXX.','Stay in one world, or bring a few favorites together.',`<div class="segmented"><button type="button" data-action="mode" data-mode="single" class="${S.draft.mode==='single'?'active':''}">One MIXX</button><button type="button" data-action="mode" data-mode="blend" class="${S.draft.mode==='blend'?'active':''}">My Mix</button></div>`)+worldCards(selected)+
 `<section class="section grid cols2"><div class="panel"><div class="eyebrow">MAKE IT YOURS</div><h2>${h(mixName())}</h2>${S.draft.mode==='blend'?selected.map(id=>{const w=WORLDS.find(w=>w.id===id);return `<div class="weight-row"><b>${h(w.name)}</b><div class="segmented">${['less','normal','more'].map(v=>`<button data-action="weight" data-world="${id}" data-weight="${v}" class="${S.draft.worlds[id]===v?'active':''}" aria-pressed="${S.draft.worlds[id]===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div>`;}).join(''):''}
 ${selected.map(id=>{const w=WORLDS.find(w=>w.id===id),chosen=S.draft.subcategories[id]||[];return `<div class="section"><span class="label">${h(w.name)} · What kind?</span><small>Leave these off to play everything in this world.</small><div class="options">${w.choices.map(c=>`<button class="pill ${chosen.includes(c)?'selected':''}" data-action="subcategory" data-world="${id}" data-value="${h(c)}" aria-pressed="${chosen.includes(c)}">${h(c)}</button>`).join('')}</div></div>`;}).join('')}
 <label class="field"><span class="label">Rotation length</span><select id="mix-length"><option value="90" ${S.draft.minutes===90?'selected':''}>90 minutes · a quick mix</option><option value="180" ${S.draft.minutes===180?'selected':''}>3 hours · recommended</option><option value="360" ${S.draft.minutes===360?'selected':''}>6 hours · full service</option></select></label><div class="actions">${button('Save this MIXX','save-mix','secondary')}${button(icon('play')+' '+(S.data.tvs.length?'Play on TVs':'Save & pair a TV'),'apply-mix')}</div></div><div><section class="panel hero-player">${preview()}</section><ul class="bullets"><li>New eligible videos join future rotations automatically.</li><li>Shuffle changes the order, not your selections.</li><li>Your saved screen settings stay in place.</li></ul></div></section>`;}
function tvs(){const tvs=S.data.tvs,groups=[...new Set(tvs.map(t=>t.group_name).filter(Boolean))];return header('Every TV. One simple remote.','Choose one TV, a group, or the whole room. Your computer can disconnect once playback starts.',`<div class="actions">${button('Open TV player '+icon('arrow'),'open-player','secondary')}${button(icon('plus')+' Pair TV','pair')}</div>`)+
 (!tvs.length?empty('Your first TV starts here.','Open the player in a supported browser on your TV device. Use an HDMI-connected computer when a TV browser is unsupported.',button('Pair a TV','pair')):
 `<div class="panel"><div class="section-head"><div class="actions"><label class="check"><input type="checkbox" id="all-tvs" ${S.selected.size===tvs.length?'checked':''}>All TVs</label>${groups.map(g=>button(h(g),'group','secondary small',`data-group="${h(g)}"`)).join('')}</div><span class="small">${S.selected.size} selected</span></div><div class="actions">${['play','pause','next','shuffle'].map(k=>button(icon(k)+' '+k[0].toUpperCase()+k.slice(1),'remote','secondary',`data-kind="${k}" data-selected="true"`)).join('')}${button('Change MIXX','nav','ghost','data-page="mixx"')}</div><div class="player-audio-remote"><div class="player-audio-head"><div><span class="label">Player Volume</span><small>Controls MIXXWAVE player audio, not the TV’s hardware volume.</small></div><output data-volume-output>${S.playerVolume}%</output></div><input type="range" min="0" max="100" value="${S.playerVolume}" data-player-volume aria-label="Player Volume"><div class="actions"><button class="btn secondary small" type="button" data-action="audio-volume" data-selected="true">Set volume</button><button class="btn secondary small" type="button" data-action="audio-mute" data-muted="true" data-selected="true">Mute</button><button class="btn secondary small" type="button" data-action="audio-mute" data-muted="false" data-selected="true">Unmute</button></div><div class="audio-command-status" data-audio-status data-shared aria-live="polite">${h(S.audioStatus)}</div></div></div><div class="section grid cols3">${tvs.map(t=>`<article class="panel tv-card"><div class="tv-icon">${icon('tv')}<label class="check"><input type="checkbox" data-tv-select="${t.id}" ${S.selected.has(t.id)?'checked':''} aria-label="Select ${h(t.name)}"></label><span class="badge ${t.online?'':'off'}">${t.online?'<span class="dot"></span> Connected':'Offline'}</span></div><h3>${h(t.name)}</h3><p class="small">${h(t.current_title||'No playback reported yet')}</p><div class="facts"><span>Downloaded<b>${Math.floor(t.cache_seconds/60)} min · ${(t.cache_bytes/1024/1024).toFixed(1)} MB</b></span><span>Group<b>${h(t.group_name||'Ungrouped')}</b></span><span>Last seen<b>${t.last_seen?new Date(t.last_seen).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'Not connected'}</b></span><span>Last command<b>${t.last_ack?'Confirmed #'+t.last_ack:'No receipt yet'}</b></span></div><div class="actions">${button('Remote','tv-remote','secondary small',`data-id="${t.id}"`)}${button('Edit','edit-tv','ghost small',`data-id="${t.id}"`)}</div></article>`).join('')}</div>`)+note('Offline commands expire after five minutes. A queued command is not a playback confirmation. Local playback requires previously downloaded files.');}
function schedule(){return schedulePage({venue:S.data.venue,rows:S.data.schedules});}
function commerce(){const cards=[['barrel-pick','glass','Barrel picks','Put your venue’s pick in the rotation.'],['exclusive-label','glass','Venue exclusives','Your label. Your audience.'],['event','calendar','Events','Tastings, dinners & special nights.'],['referral','link','Venue referrals','Bring another venue into MIXXTANK.']];return header('Make it your venue’s channel.','Create simple on-screen promotions. Commerce requests and bottle availability still need fulfillment outside the app.')+
 `<div class="grid cols4">${cards.map(([id,i,name,desc])=>`<section class="panel"><span class="mini-icon">${icon(i)}</span><h3 class="section">${name}</h3><p class="small section">${desc}</p><div class="actions section">${button('Create promotion','promotion','secondary small',`data-kind="${id}"`)}</div></section>`).join('')}</div><section class="section panel"><div class="section-head"><h2>Your promotions</h2><small>Included in the player overlay during their scheduled window</small></div>${S.data.promotions.some(p=>p.active)?S.data.promotions.filter(p=>p.active).map(p=>`<div class="list-row"><div><h3>${h(p.title)}</h3><p>${h(p.description)}</p><small>${date(p.starts_at)} – ${date(p.ends_at)}</small></div>${button('Stop','stop-promotion','secondary small',`data-id="${p.id}"`)}</div>`).join(''):empty('Give your guests something to look forward to.','An event, a new release, or the story behind your venue’s bottle.','','megaphone')}</section>`;}
function revenue(){const r=S.revenue;if(!r)return header('Earnings & your QR.','Loading your records…');return header('Your screen. Your opportunity.','Every figure below comes from saved scan, order, or ledger records.',button(icon('download')+' Export ledger','export-ledger','secondary'))+stats()+
 `<div class="section grid cols2"><section class="panel"><div class="eyebrow">YOUR VENUE QR</div><div class="qr-block"><img src="${h(r.qrImage)}" alt="${h(S.data.venue.name)} QR code"><div><h2>One venue. One identity.</h2><p class="small section">TV and campaign QR codes retain their own context.</p><div class="actions section">${button(icon('download')+' QR','download-qr','secondary small')}${button('Preview landing','preview-qr','ghost small')}</div></div></div><p class="small section">${h(r.qrUrl)}</p></section><section class="panel"><div class="eyebrow">ACCRUED BALANCE</div><div class="price">${money(r.metrics.balanceCents)}</div><p class="small">After recorded refunds and external payouts.</p><ul class="bullets"><li>No bank transfer is made by this dashboard.</li> <li>${r.rateConfigured?'The configured commission rate is captured when each order arrives.':'Revenue-share terms have not been configured yet.'}</li><li>Audience dwell is not measured by this player.</li></ul></section></div><div class="section panel"><div class="section-head"><h2>Revenue ledger</h2><span class="small">Latest 200 entries · append-only</span></div>${r.ledger.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Activity</th><th>Amount</th><th>Reference</th></tr></thead><tbody>${r.ledger.map(l=>`<tr><td>${date(l.created_at)}</td><td>${h(l.kind)}</td><td>${money(l.amount_cents)}</td><td>${h(l.reference)}</td></tr>`).join('')}</tbody></table></div>`:empty('No earnings recorded yet.','Once a connected merchant reports an attributed settled order, its commission appears here.','','chart')}</div><div class="section panel"><h2>Invite another venue</h2><p class="small section">${h(r.referralUrl)}</p><div class="actions">${button('Copy referral link','copy-referral','secondary')}</div><p class="small section">${r.referrals.length} venue referral${r.referrals.length===1?'':'s'} recorded. Referral rewards require approved program terms.</p></div>`;}
function billingPage(){const b=S.billing;if(!b)return header('A clear plan for every room.','Loading billing…');const bullets={free:['Sponsored programming','Venue QR & attribution','Bring your own compatible device'],paid:['No third-party sponsor videos','Price per licensed TV','Your QR and venue promotions stay'],premium:['Ad-free, clean-filtered library','Premium-eligible programming','Your QR and venue promotions stay']};return header('A clear plan for every room.','Choose the experience, then the number of TVs. Prices are loaded from your configured billing products.',b.subscription?button('Manage subscription','billing-portal','secondary'):'')+
 `<div class="grid cols3">${b.plans.map(p=>`<section class="panel plan-card"><div class="eyebrow">${S.data.venue.plan===p.id?'YOUR CURRENT PLAN':'MIXXTANK'}</div><h2>${h(p.name)}</h2><div class="price">${p.amount===null?'Not priced':money(p.amount)}${p.amount===null?'':'<small> / TV / month</small>'}</div><ul class="bullets">${bullets[p.id].map(t=>`<li>${t}</li>`).join('')}</ul><div class="actions section">${p.id==='free'?`<span class="badge">${S.data.venue.plan==='free'?'Active':'Change in billing portal'}</span>`:button(b.subscription?'Manage plan':'Choose '+h(p.name),'choose-plan','secondary',`data-plan="${p.id}" ${!p.available?'disabled':''}`)}</div></section>`).join('')}</div>${!b.connected?'<div class="alert section">Billing is not connected yet. No payment can be taken and no paid plan is activated by a button click.</div>':''}
 <section class="section"><div class="section-head"><div><h2>Hardware & professional installation</h2><p>Only with an approved, signed 5- or 10-year agreement. Not included in month-to-month service.</p></div></div><div class="grid cols2">${[5,10].map(years=>`<div class="panel"><div class="eyebrow">${years}-YEAR PARTNER AGREEMENT</div><h2>${years===5?'We bring the player.':'A fully managed installation.'}</h2><ul class="bullets"><li>Qualifying MIXXTANK-funded equipment.</li><li>Professional installation and initial setup.</li><li>Service scope defined in the signed agreement.</li></ul><div class="actions section">${button('Request eligibility review','contract','secondary',`data-years="${years}"`)}</div></div>`).join('')}</div><div class="section panel"><h3>Installation requests</h3>${S.data.contracts.length?S.data.contracts.map(c=>`<div class="list-row"><p>${c.years} years · ${c.tvs} TVs</p><span class="badge ${c.status==='approved'?'':'warn'}">${h(c.status)}</span></div>`).join(''):'<p class="small section">No request yet. Submitting a request does not sign an agreement or authorize hardware.</p>'}</div></section>`;}
function adminPage(){const a=S.admin;if(!a)return header('MIXXTANK Admin','Loading…');return header('The control room.','Publish only licensed, ready-to-play content. Settings here affect the network.',`<div class="actions">${button('Import Bunny library','import-bunny','secondary',a.integrations.bunny?'':'disabled title="Add Bunny configuration before importing"')}${button('Archive original to R2','archive','secondary',a.integrations.r2?'':'disabled title="Add R2 configuration before archiving"')}${S.config.demo?button('Load test films','demo-content'):''}</div>`)+
 `<p class="small">Review video connectivity in <a href="/setup">Connections</a>. Imported videos stay in draft until you review their rights and publish them.</p>`+environmentPanel(a.environments)+
 `<div class="grid cols4">${Object.entries(a.integrations).map(([key,ready])=>`<div class="panel"><div class="health">${icon(ready?'check':'settings')}<b>${key.toUpperCase()}</b></div><span class="badge ${ready?'':'off'}">${ready?'Credentials configured':'Not connected'}</span></div>`).join('')}</div><div class="section panel"><div class="section-head"><h2>Content library</h2><small>${a.content.length} items · imported items start as drafts</small></div>${a.content.length?`<div class="table-wrap"><table><thead><tr><th>Title</th><th>Worlds</th><th>Status</th><th>Rights</th><th></th></tr></thead><tbody>${a.content.map(c=>`<tr><td>${h(c.title)}</td><td>${h(JSON.parse(c.worlds).join(', ')||'Uncategorized')}</td><td><span class="badge ${c.status==='published'?'':'off'}">${h(c.status)}</span></td><td>${c.rights_confirmed?'Confirmed':'Review required'}</td><td>${button('Edit','edit-content','secondary small',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Connect your media library.','Import Bunny videos, choose their worlds, confirm venue-playback rights, and publish.','','cloud')}</div><div class="section grid cols2"><section class="panel"><div class="section-head"><h2>Brand campaigns</h2>${button('Create','campaign','secondary small')}</div>${a.campaigns.map(c=>`<div class="list-row"><div><b>${h(c.name)}</b><p>${h(c.brand_id)} · ${h(c.world)}</p></div><span class="badge">${c.active?'Active':'Draft'}</span></div>`).join('')||'<p class="small">No campaigns yet.</p>'}</section><section class="panel"><h2>Installation approvals</h2>${a.contracts.map(c=>`<div class="list-row"><div><b>${h(c.venue_name)}</b><p>${c.years} years · ${c.tvs} TVs</p></div>${c.status==='requested'?button('Review','approve-contract','secondary small',`data-id="${c.id}"`):`<span class="badge">${h(c.status)}</span>`}</div>`).join('')||'<p class="small section">No installation requests.</p>'}</section></div><div class="section panel"><div class="section-head"><h2>Finance & audit</h2>${button('Record external payout','payout','secondary small')}</div>${a.audit.slice(0,12).map(a=>`<div class="list-row"><span class="small">${h(a.action)}</span><span class="small">${date(a.created_at)}</span></div>`).join('')}</div>`;}
function brandPage(){const b=S.brands;if(!b)return header('What your campaign actually did.','Loading…');return header('What your campaign actually did.','Campaign-scoped reporting. No invented audience counts.')+`<div class="alert">${h(b.measurement)}</div><section class="section panel">${b.campaigns.length?`<div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Reported screen-hours</th><th>QR scans</th><th>Attributed sales</th><th>Audience dwell</th></tr></thead><tbody>${b.campaigns.map(c=>`<tr><td>${h(c.name)}</td><td>${(c.seconds/3600).toFixed(2)}</td><td>${c.scans}</td><td>${money(c.salesCents)}</td><td>Not measured</td></tr>`).join('')}</tbody></table></div>`:empty('No campaigns in this account.','This report shows delivered campaign activity once a campaign is assigned to your account. Venue playback is available in MIXDATA.','','chart')}</section>`;}
function renderAuth(){const signup=S.auth==='signup'&&S.config?.signups;$('#app').innerHTML=`<div class="auth"><aside class="auth-story"><div><div class="wordmark"><img src="/icon.svg" alt="">MIXX<span>PRO</span></div></div><div><div class="eyebrow" style="color:#b6c5ab">YOUR ROOM. YOUR MIXX.</div><h1>Give your screens<br>some atmosphere.</h1><p>A world of great stories, curated for your venue. Pick your MIXX. We’ll handle the rotation.</p><ul class="bullets"><li>Golf, bourbon, travel, and more.</li><li>Your look. Your promotions. Your TVs.</li><li>One simple remote, wherever you are.</li></ul></div><small style="color:#92a68d">MIXXTANK · Better stories belong here.</small></aside><main class="auth-form" id="main"><div class="auth-steps">${S.config?.demo?'Local pilot · test content only':'Venue access'}</div><h2>${signup?'Welcome to your next favorite channel.':'Good to have you back.'}</h2><p>${signup?'Create your venue. No payment required.':'Sign in to your venue dashboard.'}</p><form id="auth-form" data-form="auth">${signup?`<div class="grid cols2"><label class="field"><span class="label">Your name</span><input name="name" autocomplete="name" required maxlength="80" placeholder="Jordan"></label><label class="field"><span class="label">Venue name</span><input name="venueName" autocomplete="organization" required maxlength="80" placeholder="Oak & Ember"></label></div>`:''}<label class="field"><span class="label">Email</span><input name="email" type="email" autocomplete="email" required placeholder="you@yourvenue.com"></label><label class="field"><span class="label">Password ${signup?'· 12 characters minimum':''}</span><input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required ${signup?'minlength="12"':''} maxlength="200"></label>${signup?`<div class="grid cols2"><label class="field"><span class="label">Venue type</span><select name="type"><option value="golf">Golf club</option><option value="bourbon-bar">Bourbon bar</option><option value="cigar">Cigar lounge</option><option value="steakhouse">Steakhouse</option><option value="other">Other venue</option></select></label><label class="field"><span class="label">Timezone</span><select name="timezone">${['America/Chicago','America/New_York','America/Denver','America/Los_Angeles','America/Phoenix','America/Anchorage','Pacific/Honolulu','Europe/London','UTC'].map(t=>`<option>${t}</option>`).join('')}</select></label></div>`:''}<div class="form-error" role="alert"></div><button class="btn" type="submit">${signup?'Create my venue':'Sign in'} ${icon('arrow')}</button></form>${S.config?.signups?`<button class="auth-switch" data-action="auth-switch">${signup?'Already have an account? Sign in':'New here? Create a venue'}</button>`:''}<p class="auth-note">${signup?'Free service uses your own compatible hardware. Funded installation requires an approved 5- or 10-year agreement.':'Pilot password recovery is handled by your MIXXPRO administrator.'}</p></main></div>`;}
let disposeGameHost=()=>{},disposeBillboards=()=>{};
function render(){
  const menuOpen=!!document.querySelector('.sidebar.open'),settingsOpen=!!document.querySelector('nav [data-stream-settings]')?.open;
  disposeGameHost();disposeGameHost=()=>{};disposeBillboards();disposeBillboards=()=>{};
  if(!S.session){renderAuth();return;}
  if(!S.data&&!['admin','brands'].includes(S.page)){S.page=S.session.user.role==='admin'?'admin':S.session.user.role==='brand'?'brands':'home';}
  const menu=[['home','home'],['mixx','play'],['tvs','tv'],['schedule','calendar'],['commerce','megaphone'],['revenue','chart']];
  if(S.data&&S.session.venues.find(v=>v.id===S.venueId)?.role!=='viewer')menu.push(['games','flag']);
  if(S.session.user.role==='admin')menu.push(['admin','shield']);if(['admin','brand'].includes(S.session.user.role))menu.push(['brands','chart']);
  const body=({home,mixx,tvs,schedule,commerce:billboardPage,revenue,billing:billingPage,games:gameHostPage,admin:adminPage,brands:brandPage})[S.page];
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar${menuOpen?' open':''}"><div class="sidebar-head"><div class="wordmark"><img src="/icon.svg" alt="">MIXX<span>PRO</span></div><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button></div><div class="tagline">Your room. Your MIXX.</div><select class="venue-picker" id="venue-select" aria-label="Current venue">${S.session.venues.map(v=>`<option value="${v.id}" ${v.id===S.venueId?'selected':''}>${h(v.name)}</option>`).join('')||'<option>Network access</option>'}</select><div class="nav-label">YOUR VENUE</div><nav class="navigation" data-settings-open="${settingsOpen}" aria-label="Main navigation">${menu.filter(([key])=>S.data||['admin','brands'].includes(key)).map(([key,i])=>`<button data-action="nav" data-page="${key}" class="${S.page===key?'active':''}" ${S.page===key?'aria-current="page"':''}>${icon(i)}${paths[key]}</button>`).join('')}</nav><div class="nav-footer"><span class="badge">${h(S.data?.venue.plan||S.session.user.role)}</span><p>Great stories. Less busywork.</p><button data-action="support">${icon('help')} Help connecting</button><br><button data-action="logout">Sign out</button></div></aside><main class="main" id="main"><div class="topbar"><div class="breadcrumb">Your workspace <span>/</span> ${paths[S.page]}</div><div class="topbar-right">${S.config.demo?'<span class="badge demo">DEMO CONTENT MODE</span>':''}<button class="btn ghost small mobile-menu" data-action="logout" aria-label="Sign out">Exit</button><button class="btn ghost help-link" data-action="new-venue">${icon('plus')} Add venue</button><span class="avatar" title="${h(S.session.user.name)}">${h(S.session.user.name.slice(0,2).toUpperCase())}</span></div></div>${S.data||['admin','brands'].includes(S.page)?body():empty('Create your venue.','Add a venue to start programming.',button('Create venue','new-venue'))}</main></div>`;
  if(S.data?.role==='viewer'&&S.page==='schedule'){for(const control of document.querySelectorAll('.main [data-action="schedule"],.main [data-action="remove-schedule"]'))control.disabled=true;const message=document.createElement('p');message.className='alert';message.textContent='View only. A venue owner or manager can change these settings.';document.querySelector('.main .header')?.after(message);}
  if(S.page==='commerce'&&S.data)disposeBillboards=mountBillboards({root:document.querySelector('[data-billboards]'),api});
  if(S.page==='games'&&S.data)disposeGameHost=mountGameHost({root:document.querySelector('[data-game-host]'),api,demo:S.config.demo,isAdmin:S.session.user.role==='admin',onNavigate:navigate});
  if(S.data?.role==='viewer')for(const control of document.querySelectorAll('#app [data-action]'))if(venueWrites.has(control.dataset.action))control.disabled=true;
}
async function loadData(reset=false){if(S.venueId){S.data=await api('/venue');if(reset){S.draft=clone(S.data.venue.mix);S.theme=S.data.venue.theme;S.accent=S.data.venue.accent;S.selected=new Set(S.data.tvs.map(t=>t.id));}}}
async function loadPage(){if(S.page==='revenue')S.revenue=await api('/revenue');if(S.page==='billing')S.billing=await api('/billing');if(S.page==='admin'){const [a,e]=await Promise.all([api('/admin'),api('/admin/environments')]);S.admin={...a,environments:e.environments};}if(S.page==='brands')S.brands=await api('/brands');}
async function navigate(page){if(page===S.page)return;if(S.page==='commerce'&&disposeBillboards.canLeave?.()===false)return;document.querySelector('.sidebar')?.classList.remove('open');S.page=page;if(['home','tvs'].includes(page))await loadData();await loadPage();render();window.scrollTo({top:0,behavior:'instant'});}
async function start(){S.config=await api('/config');try{S.session=await api('/session');if(!S.session.venues.some(v=>v.id===S.venueId))S.venueId=S.session.venues[0]?.id||'';localStorage.setItem('mixx-venue',S.venueId);await loadData(true);if(!S.venueId)S.page=S.session.user.role==='brand'?'brands':'admin';await loadPage();}catch(e){if(e.status!==401)toast(e.message,true);S.session=null;}render();}
function modal(title,content,formType,buttons='Save'){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${formType?`<form data-form="${formType}">${content}<div class="form-error" role="alert"></div><div class="dialog-actions">${button('Cancel','close','secondary')}<button class="btn" type="submit">${buttons}</button></div></form>`:content}`;d.showModal();}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span class="label">${label}</span><input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;}
function select(label,name,values,current){return `<label class="field"><span class="label">${label}</span><select name="${name}">${values.map(([value,name])=>`<option value="${h(value)}" ${value===current?'selected':''}>${h(name)}</option>`).join('')}</select></label>`;}
function showTargets(kind,ids){if(!S.data.tvs.length){showPair();return;}modal(kind==='apply'?'Where should this play?':'Choose your TVs',`<p>Commands are queued now and confirmed by the connected players.</p><input type="hidden" name="kind" value="${kind}">${S.data.tvs.map(t=>`<label class="check"><input type="checkbox" name="tv" value="${t.id}" ${!ids||ids.includes(t.id)?'checked':''}><b>${h(t.name)}</b> <span class="small">${t.online?'Connected':'Offline · command waits up to 5 minutes'}</span></label>`).join('')}`, 'targets',kind==='apply'?'Apply to selected TVs':kind[0].toUpperCase()+kind.slice(1));}
function audioStatus(rows){return rows.map(row=>`${h(row.tvName||S.data.tvs.find(t=>t.id===row.tvId)?.name||'TV')}: ${row.status==='applied'?'Applied':row.status==='blocked'?'Blocked':row.status==='offline'?'Offline':'Pending'}${row.detail?' · '+h(row.detail):''}`).join(' · ');}
function setAudioStatus(target,rows){const value=audioStatus(rows);if(target?.dataset.shared!==undefined){S.audioStatus=value;const live=document.querySelector('[data-audio-status][data-shared]');if(live)live.innerHTML=value;}else if(target?.isConnected)target.innerHTML=value;}
async function trackAudio(commands,target){if(!target)return;let rows=commands;setAudioStatus(target,rows);const ids=commands.map(c=>c.id).join(',');for(let n=0;n<20&&rows.some(r=>r.status==='pending');n++){await new Promise(resolve=>setTimeout(resolve,750));const result=await api('/commands/status?ids='+encodeURIComponent(ids));rows=result.commands;setAudioStatus(target,rows);}return rows;}
async function sendAudio(kind,ids,volume,target){if(!ids.length){toast('Select at least one TV.',true);return;}const body={kind,ids};if(kind==='volume')body.volume=Math.max(0,Math.min(100,Number(volume)));else body.muted=!!volume;const queued=await api('/commands',body);await trackAudio(queued.commands,target);}
function showPair(){modal('Connect a TV.',`<ol class="bullets"><li>Open <b>${h(location.origin)}/player/</b> on the TV’s browser or HDMI-connected player.</li><li>Read the six-digit code on that screen.</li><li>Enter it below and give your TV a name.</li></ol>${field('Pairing code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="123456"')}${field('TV name','name','','text','required maxlength="60" placeholder="Main bar"')}${field('Group (optional)','group','','text','maxlength="40" placeholder="Dining room"')}`, 'pair','Connect TV');}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let pendingApply={};
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
  if(S.data?.role==='viewer'&&venueWrites.has(a)){toast('View only. A venue owner or manager can change playback.',true);return;}
  try{
    if(a==='nav')return await navigate(el.dataset.page);
    if(a==='edit-environment'){openEnvironmentEditor({environment:S.admin.environments.find(e=>e.id===el.dataset.id),venues:S.admin.venues,api,onSaved:async()=>{await loadPage();render();}});return;}
    if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');return;}
    if(a==='close'){$('#dialog').close();return;}
    if(a==='auth-switch'){S.auth=S.auth==='signup'?'login':'signup';render();return;}
    if(a==='logout'){if(S.page==='commerce'&&disposeBillboards.canLeave?.()===false)return;await api('/auth/logout',{});S.session=null;S.data=null;render();return;}
    if(a==='refresh-venue'){el.disabled=true;await loadData();render();return;}
    if(a==='open-player'){window.open('/player/','_blank','noopener');return;}
    if(a==='world'){
      if(S.page==='home'){S.draft={...clone(defaultMix),worlds:{[el.dataset.id]:'normal'}};return await navigate('mixx');}
      const id=el.dataset.id;if(S.draft.mode==='single'){S.draft.worlds={[id]:'normal'};S.draft.subcategories={};}else if(S.draft.worlds[id]){if(Object.keys(S.draft.worlds).length===1)return toast('Keep at least one world in your mix.');delete S.draft.worlds[id];delete S.draft.subcategories[id];}else S.draft.worlds[id]='normal';render();return;
    }
    if(a==='mode'){S.draft.mode=el.dataset.mode;if(S.draft.mode==='single'){const first=Object.keys(S.draft.worlds)[0];S.draft.worlds={[first]:'normal'};S.draft.subcategories={[first]:S.draft.subcategories[first]||[]};}render();return;}
    if(a==='weight'){S.draft.worlds[el.dataset.world]=el.dataset.weight;render();return;}
    if(a==='subcategory'){const w=el.dataset.world,v=el.dataset.value,old=S.draft.subcategories[w]||[];S.draft.subcategories[w]=old.includes(v)?old.filter(x=>x!==v):[...old,v];render();return;}
    if(a==='save-mix'){await api('/venue',{mix:S.draft},'PATCH');await loadData();toast('Your venue MIXX is saved. Apply it to TVs when you’re ready.');return;}
    if(a==='apply-mix'){if(!S.data.tvs.length){el.disabled=true;await api('/venue',{mix:S.draft},'PATCH');await loadData();showPair();toast('MIXX saved. Pair your TV to start it.');return;}pendingApply={mix:clone(S.draft)};showTargets('apply');return;}
    if(a==='remote'){showTargets(el.dataset.kind,el.dataset.selected?[...S.selected]:null);return;}
    if(a==='tv-remote'){const t=S.data.tvs.find(t=>t.id===el.dataset.id);modal(h(t.name),`<p>Choose a playback action for this TV.</p><div class="actions section">${['play','pause','next','shuffle'].map(k=>button(icon(k)+' '+k,'quick-command','secondary',`data-kind="${k}" data-id="${t.id}"`)).join('')}</div><div class="player-audio-remote section"><div class="player-audio-head"><div><span class="label">Player Volume</span><small>MIXXWAVE player audio only; not hardware/TV system volume.</small></div><output data-volume-output>70%</output></div><input type="range" min="0" max="100" value="70" data-player-volume aria-label="Player Volume"><div class="actions"><button class="btn secondary small" type="button" data-action="audio-volume" data-id="${t.id}">Set volume</button><button class="btn secondary small" type="button" data-action="audio-mute" data-muted="true" data-id="${t.id}">Mute</button><button class="btn secondary small" type="button" data-action="audio-mute" data-muted="false" data-id="${t.id}">Unmute</button></div><div class="audio-command-status" data-audio-status aria-live="polite">${t.online?'Ready.':'Offline.'}</div></div>`);return;}
    if(a==='quick-command'){const r=await api('/commands',{kind:el.dataset.kind,ids:[el.dataset.id]});$('#dialog').close();toast(r.message);return;}
    if(a==='audio-volume'){const scope=el.closest('.player-audio-remote'),range=scope.querySelector('[data-player-volume]'),ids=el.dataset.selected?[...S.selected]:[el.dataset.id];await sendAudio('volume',ids,Number(range.value),scope.querySelector('[data-audio-status]'));return;}
    if(a==='audio-mute'){const scope=el.closest('.player-audio-remote'),ids=el.dataset.selected?[...S.selected]:[el.dataset.id];await sendAudio('mute',ids,el.dataset.muted==='true',scope.querySelector('[data-audio-status]'));return;}
    if(a==='pair'){showPair();return;}
    if(a==='group'){S.selected=new Set(S.data.tvs.filter(t=>t.group_name===el.dataset.group).map(t=>t.id));render();return;}
    if(a==='edit-tv'){const t=S.data.tvs.find(t=>t.id===el.dataset.id);modal('TV details',`<input type="hidden" name="id" value="${t.id}">${field('TV name','name',t.name,'text','required maxlength="60"')}${field('Group','group',t.group_name)}<div class="alert">Revoking disconnects the player at its next check-in. Cached playback can continue until its six-hour lease expires if it is offline.</div><div class="actions section">${button('Revoke TV access','revoke-tv','danger small',`data-id="${t.id}"`)}</div>`,'tv-edit');return;}
    if(a==='revoke-tv'){if(!confirm('Revoke this TV’s access?'))return;await api('/tvs/'+el.dataset.id,{revoke:true},'PATCH');$('#dialog').close();await loadData();render();toast('TV access revoked.');return;}
    if(a==='schedule'){const venueId=S.venueId;openScheduleEditor({dialog:$('#dialog'),modal,api,venue:S.data.venue,currentMix:S.draft,rows:S.data.schedules,id:el.dataset.id,onSaved:async()=>{if(S.venueId!==venueId)return;try{await loadData();render();toast('Schedule saved.');}catch{toast('Schedule saved. Refresh the page to see it.',true);}}});return;}
    if(a==='remove-schedule'){const row=S.data.schedules.find(s=>s.id===el.dataset.id);if(!row||!confirm(`Remove “${row.name}” from the schedule?`))return;await api('/schedules/'+el.dataset.id,{},'DELETE');await loadData();render();toast('Schedule removed.');return;}
    if(a==='promotion'){const kind=el.dataset.kind;modal('Give your guests a reason.',`<input type="hidden" name="kind" value="${kind}">${field('Title','title','','text','required maxlength="80" placeholder="Friday tasting at 7"')}${field('Short description','description','','text','required maxlength="200" placeholder="Meet the maker. Ask your bartender for details."')}<div class="grid cols2">${field('Start date','start',new Date().toISOString().slice(0,10),'date','required')}${field('End date','end',new Date(Date.now()+7*86400000).toISOString().slice(0,10),'date','required')}</div><p class="small">Promotions appear over the TV picture while active. This does not book a barrel pick or create an exclusive-label order.</p>`,'promotion','Create promotion');return;}
    if(a==='stop-promotion'){await api('/promotions/'+el.dataset.id,{},'DELETE');await loadData();render();toast('Promotion stopped.');return;}
    if(a==='preview-qr'){window.open(S.revenue.qrUrl,'_blank','noopener');return;}
    if(a==='download-qr'){download(await (await fetch(S.revenue.qrImage)).text(),'image/svg+xml','mixtank-venue-qr.svg');return;}
    if(a==='copy-referral'){await navigator.clipboard.writeText(S.revenue.referralUrl);toast('Referral link copied.');return;}
    if(a==='export-ledger'){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Date','Kind','Amount cents','Currency','Reference'],...S.revenue.ledger.map(l=>[new Date(l.created_at).toISOString(),l.kind,l.amount_cents,l.currency,l.reference])];download(rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv','mixxpro-revenue-ledger.csv');return;}
    if(a==='choose-plan'){if(S.billing.subscription){location.href=(await api('/billing/portal',{})).url;return;}const p=S.billing.plans.find(p=>p.id===el.dataset.plan);modal('Your plan. Your TV count.',`<input type="hidden" name="plan" value="${p.id}"><p>${h(p.name)} · ${money(p.amount)} per TV per month.</p>${field('Licensed TVs','seats',Math.max(1,S.data.tvs.length),'number','required min="1" max="100"')}<p class="small">Stripe shows your final total and any applicable taxes before you pay. Hardware and installation are not included.</p>`,'checkout','Continue to secure checkout');return;}
    if(a==='billing-portal'){location.href=(await api('/billing/portal',{})).url;return;}
    if(a==='contract'){modal('Request an installation review.',`<input type="hidden" name="years" value="${el.dataset.years}"><p><b>${el.dataset.years}-year partner agreement</b></p><ul class="bullets"><li>We review your venue and hardware requirements.</li><li>Equipment funding requires a signed, approved agreement.</li><li>This request is not a contract or a promise of coverage.</li></ul>${field('How many TVs?','tvs',Math.max(1,S.data.tvs.length),'number','required min="1" max="100"')}`,'contract','Submit request');return;}
    if(a==='new-venue'){modal('Add another venue.',`${field('Venue name','name','','text','required maxlength="80"')}${select('Venue type','type',[['golf','Golf club'],['bourbon-bar','Bourbon bar'],['cigar','Cigar lounge'],['steakhouse','Steakhouse'],['other','Other']])}${field('Timezone','timezone',S.data?.venue.timezone||'America/Chicago','text','required')}`,'venue','Create venue');return;}
    if(a==='support'){modal('Let’s get the TV connected.',`<ol class="bullets"><li>Open <b>${h(location.origin)}/player/</b> on a supported browser attached to the TV.</li><li>Choose Pair TV here and enter its six-digit code.</li><li>Select a MIXX and apply it to the TV.</li><li>Click Enable playback on the TV if its browser asks for permission.</li><li>Use Ethernet when available. Keep power and the player running.</li></ol><div class="alert section">Native smart-TV apps, automatic casting, and kiosk hardware certification are not included in this pilot. An HDMI-connected browser player is the test path.</div>`);return;}
    if(a==='import-bunny'){el.disabled=true;const r=await api('/admin/media/import',{page:1});await loadPage();render();toast(`${r.added} videos imported as drafts. Library total: ${r.totalItems||0}.`);return;}
    if(a==='demo-content'){await api('/admin/demo-content',{});await loadPage();render();toast('Test films loaded. They are explicitly labeled as samples.');return;}
    if(a==='edit-content'){const c=S.admin.content.find(c=>c.id===el.dataset.id),worlds=JSON.parse(c.worlds);modal('Prepare this video.',`<input type="hidden" name="id" value="${c.id}">${field('Title','title',c.title,'text','required maxlength="160"')}<span class="label">Content worlds</span><div class="options">${WORLDS.map(w=>`<label class="check"><input type="checkbox" name="world" value="${w.id}" ${worlds.includes(w.id)?'checked':''}>${h(w.name)}</label>`).join('')}</div>${field('Subcategory tags (comma separated)','tags',JSON.parse(c.tags).join(', '))}<div class="grid cols2">${select('Status','status',[['draft','Draft'],['published','Published']],c.status)}${select('MP4 resolution','resolution',[['360','360p'],['480','480p'],['720','720p'],['1080','1080p']],String(c.resolution))}</div>${[['clean','Clean language/content',c.clean],['premiumOnly','Premium-only',c.premium_only],['sponsor','Sponsored video',c.sponsor],['rightsConfirmed','Venue exhibition + local-cache rights confirmed',c.rights_confirmed]].map(([n,l,v])=>`<label class="check"><input type="checkbox" name="${n}" ${v?'checked':''}>${l}</label>`).join('')}${field('Rights expiration (optional)','rightsUntil',c.rights_until?new Date(c.rights_until).toISOString().slice(0,10):'','date')}<p class="small">Publishing checks Bunny encoding and MP4 accessibility. Drafts are never sent to TVs.</p>`,'content','Save video');return;}
    if(a==='archive'){modal('Archive an original.',`<p>Upload directly to your private Cloudflare R2 master-file bucket.</p><label class="field"><span class="label">Original file</span><input type="file" name="file" accept="video/mp4,video/quicktime,image/png,image/jpeg,image/webp,text/vtt" required></label><p class="small">This archives the original; import its streaming version separately through Bunny. Single uploads up to 5 GB; use R2 tooling for larger files.</p>`,'archive','Upload to R2');return;}
    if(a==='campaign'){const ads=S.admin.content.filter(c=>c.sponsor&&c.status==='published');modal('Create a brand campaign.',`${field('Campaign name','name','','text','required')}${field('Brand account ID','brandId','','text','required')}${select('Sponsored video','contentId',ads.map(c=>[c.id,c.title]))}${select('Content world','world',WORLDS.map(w=>[w.id,w.name]))}${select('Venue targeting','venueType',[['','All venue types'],['golf','Golf'],['bourbon-bar','Bourbon bar'],['steakhouse','Steakhouse'],['cigar','Cigar lounge']])}<div class="grid cols2">${field('Start','start',new Date().toISOString().slice(0,10),'date','required')}${field('End','end',new Date(Date.now()+30*86400000).toISOString().slice(0,10),'date','required')}</div><label class="check"><input type="checkbox" name="active">Activate campaign after saving</label><p class="small">Sponsored video insertion is allowed only on the Free plan.</p>`,'campaign','Create campaign');return;}
    if(a==='approve-contract'){const c=S.admin.contracts.find(c=>c.id===el.dataset.id);modal('Approve signed agreement.',`<input type="hidden" name="id" value="${c.id}"><p>${h(c.venue_name)} · ${c.years} years · ${c.tvs} TVs</p>${field('Signed agreement reference','signedReference','','text','required maxlength="200"')}${field('Agreement expiration','expiresAt','','date','required')}<div class="alert">Approve only after checking the signed agreement. Do not paste private contract text into the public repository.</div>`,'approve','Approve hardware eligibility');return;}
    if(a==='payout'){modal('Record a completed external payout.',`${select('Venue','venueId',S.admin.venues.map(v=>[v.id,v.name]))}${field('Amount in cents','amountCents','','number','required min="1"')}${field('External payment reference','reference','','text','required')}<div class="alert">This records an already completed payment. It does not send money or call a bank.</div>`,'payout','Record external payout');return;}
  }catch(e){toast(e.message,true);}finally{if(el.isConnected)el.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-player-volume]')){S.playerVolume=Number(e.target.value);const scope=e.target.closest('.player-audio-remote');if(scope)scope.querySelector('[data-volume-output]').textContent=e.target.value+'%';}});
document.addEventListener('change',async e=>{try{
  if(e.target.id==='venue-select'){if(S.page==='commerce'&&disposeBillboards.canLeave?.()===false){e.target.value=S.venueId;return;}disposeGameHost();disposeBillboards();S.venueId=e.target.value;localStorage.setItem('mixx-venue',S.venueId);await loadData(true);await loadPage();render();}
  if(e.target.id==='mix-length')S.draft.minutes=Number(e.target.value);
  if(e.target.id==='all-tvs'){S.selected=new Set(e.target.checked?S.data.tvs.map(t=>t.id):[]);render();}
  if(e.target.dataset.tvSelect){e.target.checked?S.selected.add(e.target.dataset.tvSelect):S.selected.delete(e.target.dataset.tvSelect);render();}
}catch(e){toast(e.message,true);}});
document.addEventListener('submit',async e=>{
  const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(S.busy)return;S.busy=true;
  const submit=form.querySelector('button[type=submit]');submit.disabled=true;const fd=new FormData(form),b=Object.fromEntries(fd),kind=form.dataset.form;
  const error=form.querySelector('.form-error');if(error)error.textContent='';
  try{
    if(kind==='auth'){if(S.auth==='signup'&&S.config.signups){b.referral_code=new URL(location.href).searchParams.get('ref')||'';await api('/auth/signup',b);}else await api('/auth/login',b);await start();return;}
    if(kind==='pair')await api('/tvs/claim',b);
    if(kind==='tv-edit')await api('/tvs/'+b.id,{name:b.name,group:b.group},'PATCH');
    if(kind==='targets'){const ids=fd.getAll('tv');if(!ids.length)throw Error('Select at least one TV.');const r=await api('/commands',{kind:b.kind,ids,...(b.kind==='apply'?pendingApply:{})});toast(r.message);}
    if(kind==='promotion')await api('/promotions',{kind:b.kind,title:b.title,description:b.description,startsAt:new Date(b.start).getTime(),endsAt:new Date(b.end).getTime()+86399000});
    if(kind==='contract'){const r=await api('/contracts',{years:Number(b.years),tvs:Number(b.tvs)});toast(r.message);}
    if(kind==='checkout'){const r=await api('/billing/checkout',{plan:b.plan,seats:Number(b.seats)});location.href=r.url;return;}
    if(kind==='venue'){if(S.page==='commerce'&&disposeBillboards.canLeave?.()===false)return;const r=await api('/venues',b);S.venueId=r.venueId;await start();}
    if(kind==='content')await api('/admin/media/'+b.id,{title:b.title,worlds:fd.getAll('world'),tags:b.tags.split(',').map(t=>t.trim()).filter(Boolean),status:b.status,resolution:Number(b.resolution),clean:fd.has('clean'),premiumOnly:fd.has('premiumOnly'),sponsor:fd.has('sponsor'),rightsConfirmed:fd.has('rightsConfirmed'),rightsUntil:b.rightsUntil?new Date(b.rightsUntil).getTime()+86399000:null},'PATCH');
    if(kind==='archive'){const file=fd.get('file');if(file.size>5*1024**3)throw Error('Use R2 multipart tools for files larger than 5 GB.');const p=await api('/admin/archive-upload',{filename:file.name,contentType:file.type||'text/vtt'});submit.textContent='Uploading…';const r=await fetch(p.url,{method:'PUT',headers:p.headers,body:file});if(!r.ok)throw Error(`R2 returned ${r.status}. Check bucket CORS and credentials.`);toast('Original archived: '+p.key);}
    if(kind==='campaign')await api('/admin/campaigns',{...b,startsAt:new Date(b.start).getTime(),endsAt:new Date(b.end).getTime()+86399000,active:fd.has('active')});
    if(kind==='approve')await api('/admin/contracts/approve',{id:b.id,signedReference:b.signedReference,expiresAt:new Date(b.expiresAt).getTime()});
    if(kind==='payout'){const r=await api('/admin/payout-record',{...b,amountCents:Number(b.amountCents)});toast(r.message);}
    $('#dialog').close();await loadData();await loadPage();render();if(!['targets','contract','archive','payout'].includes(kind))toast('Saved.');
  }catch(err){if(error)error.textContent=err.message;else toast(err.message,true);}finally{S.busy=false;if(submit.isConnected)submit.disabled=false;}
});
setInterval(async()=>{if(S.session&&S.venueId&&['home','tvs'].includes(S.page)&&!$('#dialog').open&&!S.busy){try{await loadData();render();}catch(e){if(e.status===401){S.session=null;render();}}}},15000);
start().catch(e=>{document.querySelector('#app').textContent='Unable to open MIXXPRO. '+e.message;});
